/*
	Created: 20210421@Johnson
	Task: update bet limit for licensee Happy8	
*/
ALTER PROCEDURE [dbo].Acc_CustSetting3rd_19
	@custids VARCHAR(MAX)	
	,@target VARCHAR(20)
AS
BEGIN
	SET NOCOUNT ON
	
	IF (@target = 'REPLICATED' AND @@SERVERNAME IN ('DBCUST','SITDBCUST','DB233','DB230\SQLSERVER2008R2')) RETURN -- run at all replicated servers
	IF (@target = 'DBCUST' AND @@SERVERNAME NOT IN ('DBCUST','SITDBCUST','DB233','DB230\SQLSERVER2008R2')) RETURN -- run at DBCUST only
	
	IF dbo.f_CheckRepTable('Dep_CustStakeLevel_Member') = 0 RETURN
	
	CREATE TABLE #tblCust (custid INT PRIMARY KEY)
	
	INSERT INTO #tblCust(custid)
	SELECT	val
	FROM FROM dbo.f_SplitString(@custids, ',')
	OPTION (MAXRECURSION 0)
	
	DECLARE @tmp TABLE(Bettype INT, StakeLevelID VARCHAR(50),StakeLevelID_New VARCHAR(50))
	
	INSERT INTO @tmp(Bettype,StakeLevelID_new,StakeLevelID)
	SELECT 4601,8753,1163	
	UNION SELECT 4602,8756,4054
	UNION SELECT 4601,8759,1148
	UNION SELECT 4602,8762,4042
	UNION SELECT 4601,2795,1154
	UNION SELECT 4602,5869,4048
	UNION SELECT 4601,8741,1172
	UNION SELECT 4602,8744,4060
	UNION SELECT 4601,8747,1217
	UNION SELECT 4602,8750,4102

	UPDATE cs
	SET cs.StakeLevelList = CASE WHEN cs.StakeLevelID = t.StakeLevelID THEN t.StakeLevelID_New ELSE cs.StakeLevelID END
	FROM Dep_CustStakeLevel_Member cs WITH(ROWLOCK)
		INNER JOIN @tmp t ON cs.BetType = t.Bettype
	WHERE custid IN (SELECT custid FROM #tblCust)
		AND sporttype = 245
	
	DROP TABLE #tblCust
END	
GO

-- END STEP 1: DEPLOY THIS SP @DBCUST.CustDB --------
------------------------------------------------------	

-- BEGIN STEP 2: RUN THIS SCRIPT AT ALL REPLICATED SERVERS -----
--------------------------------------------------------------------------------------
