49587891	,
49587892	
)


DECLARE @custids VARCHAR(MAX) = ''

WHILE(1=1)
BEGIN		
	SET @custids = ''
	
	UPDATE TOP(2000) t	
	SET isFinished = 1,
		@custids = @custids + CAST(custid AS VARCHAR(20))
	FROM #tmpCust t
	WHERE isFinished = 0
	
	IF @@rowcount = 0
		BREAK;
	
	select @custids = stuff(@custids,1,1,'')
		
	EXEC Acc_CustSetting3rd_19 @custids = @custids,
							@target = 'REPLICATED'--change target = 'DBCUST' if run on DBCUST
	
	WAITFOR DELAY '0:0:0.028'						
	
END
--END STEP 2: RUN THIS SCRIPT AT ALL REPLICATED SERVERS -----
